// Wrong: Square inherits Rectangle, but overrides height/width independently, breaking area assertions
class Rectangle {
  protected int w, h;
  public void setWidth(int w) { this.w = w; }
  public void setHeight(int h) { this.h = h; }
}
class Square extends Rectangle {
  @Override
  public void setWidth(int w) { this.w = w; this.h = w; }
}

codeMap.good:
// Correct: Abstract shape or decouple inheritance. Keep Square and Rectangle independent
interface Shape {
  int getArea();
}
class Rectangle implements Shape {
  private int w, h;
  public int getArea() { return w * h; }
}

